#!/usr/bin/env bash
set -euo pipefail

# Run from the zk/ directory. Requires circom 2.2.3, Node.js, npm dependencies,
# and shard_merkle_vectors.json generated by the Python vector generator.
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$ROOT"

VECTORS="${1:-shard_merkle_vectors.json}"
CASE="${2:-three_shards_63_bytes}"
SHARD_INDEX="${3:-2}"
CHUNK_INDEX="${4:-2}"
BUILD="$ROOT/build"
SNARKJS="$ROOT/node_modules/.bin/snarkjs"

if [[ ! -f "$VECTORS" ]]; then
  echo "Missing vectors file: $VECTORS" >&2
  exit 1
fi
if [[ ! -x "$SNARKJS" ]]; then
  echo "Missing snarkjs. Run: npm install" >&2
  exit 1
fi
command -v circom >/dev/null || { echo "circom is not on PATH" >&2; exit 1; }
mkdir -p "$BUILD"

node shard_merkle_vectors/generate_wrapper.mjs \
  "$VECTORS" "$CASE" "$BUILD/engram_shard_post_main.circom"

node shard_merkle_vectors/generate_witness_input.mjs \
  "$VECTORS" "$CASE" "$SHARD_INDEX" "$CHUNK_INDEX" "$BUILD/input.json"

circom "$BUILD/engram_shard_post_main.circom" \
  --r1cs --wasm --sym -l node_modules -o "$BUILD"

WASM_DIR="$BUILD/engram_shard_post_main_js"
node "$WASM_DIR/generate_witness.js" \
  "$WASM_DIR/engram_shard_post_main.wasm" \
  "$BUILD/input.json" "$BUILD/witness.wtns"

# Local development-only Powers of Tau ceremony. Do not reuse these keys in
# production; production parameters require a properly audited ceremony.
# "$SNARKJS" powersoftau new bn128 14 "$BUILD/pot14_0000.ptau" -v
# ENTROPY_1="$(openssl rand -hex 32)"
# "$SNARKJS" powersoftau contribute "$BUILD/pot14_0000.ptau" \
#   "$BUILD/pot14_0001.ptau" --name="ENGRAM local test contribution" \
#   -e="$ENTROPY_1" -v
# "$SNARKJS" powersoftau prepare phase2 "$BUILD/pot14_0001.ptau" \
#   "$BUILD/pot14_final.ptau" -v

"$SNARKJS" groth16 setup "$BUILD/engram_shard_post_main.r1cs" \
  "$BUILD/powersOfTau28_hez_final_16.ptau" "$BUILD/engram_0000.zkey"
ENTROPY_2="$(openssl rand -hex 32)"
"$SNARKJS" zkey contribute "$BUILD/engram_0000.zkey" \
  "$BUILD/engram_final.zkey" --name="ENGRAM local zkey contribution" \
  -e="$ENTROPY_2" -v
"$SNARKJS" zkey export verificationkey "$BUILD/engram_final.zkey" \
  "$BUILD/verification_key.json"

"$SNARKJS" groth16 prove "$BUILD/engram_final.zkey" \
  "$BUILD/witness.wtns" "$BUILD/proof.json" "$BUILD/public.json"
"$SNARKJS" groth16 verify "$BUILD/verification_key.json" \
  "$BUILD/public.json" "$BUILD/proof.json"

echo "Groth16 proof generated and verified successfully."
echo "Artifacts are in: $BUILD"
